}
@end

// The CGColor remains valid; only the conversion result is deliberately failed.
// This tests the controller's transaction boundary, not a Core Graphics fault.
@interface UIProfileValidationConversionFailure : UIColorValue
@property(nonatomic,strong) NSError *injectedError;
@property(nonatomic) NSUInteger conversionCalls;
@end
@implementation UIProfileValidationConversionFailure
- (UIColorValue *)colorByConvertingToSpace:(CGColorSpaceRef)space error:(NSError **)error {
    self.conversionCalls++;if(error)*error=self.injectedError;return nil;
}
@end

